public class ContactDomainService {

    /**
     * Returns contacts belonging to the given accounts, grouped by the lower-cased
     * domain part of their email address. Contacts with a blank or null email are excluded.
     * Respects the running user's sharing rules (standard SOQL behaviour).
     *
     * @param accountIds Set of Account IDs to query contacts for.
     * @return Map where key is the lower-cased email domain and value is the list of contacts.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<String, List<Contact>>();
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        for (Contact c : contacts) {
            if (String.isBlank(c.Email)) {
                continue;
            }

            Integer atIndex = c.Email.lastIndexOf('@');
            if (atIndex < 0 || atIndex == c.Email.length() - 1) {
                continue;
            }

            String domain = c.Email.substring(atIndex + 1).toLowerCase();

            if (!result.containsKey(domain)) {
                result.put(domain, new List<Contact>());
            }
            result.get(domain).add(c);
        }

        return result;
    }
}
