public class ContactLookupAction {

    @InvocableMethod(Label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Build a set of emails to search for (trimmed original + lowercase variant)
        Set<String> emailSearchSet = new Set<String>();

        for (Request req : requests) {
            if (req.email != null) {
                String trimmed = req.email.trim();
                if (!trimmed.isEmpty()) {
                    emailSearchSet.add(trimmed);
                    emailSearchSet.add(String.lowercase(trimmed));
                }
            }
        }

        // Single SOQL query to fetch all matching contacts
        Map<String, Contact> bestContactByEmail = new Map<String, Contact>();

        if (!emailSearchSet.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :emailSearchSet
            ];

            for (Contact c : contacts) {
                String key = String.lowercase(c.Email);
                Contact existing = bestContactByEmail.get(key);
                if (existing == null || c.CreatedDate < existing.CreatedDate) {
                    bestContactByEmail.put(key, c);
                }
            }
        }

        // Build results in the same order as the input requests
        for (Request req : requests) {
            Result r = new Result();
            r.found = false;
            r.contactId = null;

            if (req.email != null) {
                String trimmed = req.email.trim();
                if (!trimmed.isEmpty()) {
                    Contact c = bestContactByEmail.get(String.lowercase(trimmed));
                    if (c != null) {
                        r.contactId = c.Id;
                        r.found = true;
                    }
                }
            }

            results.add(r);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(Label='Email' Required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(Label='Contact ID')
        public Id contactId;

        @InvocableVariable(Label='Found')
        public Boolean found;
    }
