@isTest
private class AddressVerificationServiceTest {

    // ─── Mocks ───────────────────────────────────────────────────────────────────

    private class NoCalloutMock implements HttpCalloutMock {
        public HttpResponse respond(HttpRequest request) {
            throw new AssertionError('No callout should have been made');
        }
    }

    private class RecordingMock implements HttpCalloutMock {
        private final HttpResponse canned;
        public HttpRequest captured;
        public Integer callCount = 0;

        public RecordingMock(HttpResponse canned) {
            this.canned = canned;
        }

        public HttpResponse respond(HttpRequest request) {
            callCount++;
            this.captured = request;
            return canned;
        }
    }

    // ─── Helpers ─────────────────────────────────────────────────────────────────

    private static Account makeAccount(String street, String city, String postal, String country) {
