            BillingPostalCode = postal,
            BillingCountry   = country
        );
    }

    private static HttpResponse okResponse(String status, String street, String city, String postal, String country) {
        HttpResponse res = new HttpResponse();
        res.setStatusCode(200);
        res.setBody(JSON.serialize(new Map<String, Object>{
            'status'  => status,
            'address' => new Map<String, Object>{
                'street'     => street,
                'city'       => city,
                'postalCode' => postal,
                'country'    => country
            }
        }));
        return res;
    }

