public class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();
        Map<String, Boolean> emailSeen = new Map<String, Boolean>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            // Set LeadSource to Web if blank
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            // Check for duplicate email (case-insensitive, trimmed)
            if (lead.Email != null && !String.isBlank(lead.Email)) {
                String normalizedEmail = lead.Email.trim().toLowerCase();
                if (emailSeen.containsKey(normalizedEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                emailSeen.put(normalizedEmail, true);
            }

            leadsToInsert.add(lead);
            originalIndices.add(i);
        }

        if (leadsToInsert.isEmpty()) {
            return result;
        }

        // Single DML statement, allOrNone = false for partial-success
        List<Database.SaveResult> saveResults = Database.insert(leadsToInsert, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult sr = saveResults[i];
            if (sr.isSuccess()) {
                result.insertedIds.add(sr.getId());
                result.successCount++;
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(originalIndices[i], String.join(messages, '; '));
            }
        }

        return result;
    }
}
