public class LogPurgeJob implements Schedulable {

    public void execute(SchedulableContext sc) {
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneHundredEightyDaysAgo = Date.today().addDays(-180);

        List<Id> idsToDelete = new List<Id>();

        // Delete non-ERROR logs older than 30 days (Level__c may be blank/null)
        for (FB_Integration_Log__c log : [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :thirtyDaysAgo
            AND (Level__c != 'ERROR' OR Level__c = NULL)
        ]) {
            idsToDelete.add(log.Id);
        }

        // Delete ERROR logs older than 180 days
        for (FB_Integration_Log__c log : [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :oneHundredEightyDaysAgo
            AND Level__c = 'ERROR'
        ]) {
            idsToDelete.add(log.Id);
        }

        if (!idsToDelete.isEmpty()) {
            DELETE idsToDelete;
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
