    private void setupMocks() {
        mockGateway   = (IBillingGateway)         mocks.mock(IBillingGateway.class);
        mockSelector  = (IOpportunitiesSelector)  mocks.mock(IOpportunitiesSelector.class);
        mockUow       = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

