        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);
        Application.UnitOfWork.setMock(mockUow);
    }

    private Opportunity createOpp(String stageName, Decimal amount, Id accountId) {
        return new Opportunity(
            Id        = idGen.newId(Opportunity.SObjectType),
            AccountId = accountId,
            StageName = stageName,
            Amount    = amount
        );
    }

    // ─── Contract 1: authenticate called first; BillingException → InvoicingException ───

    @isTest
    private void test_authenticateFailure_throwsInvoicingException_withGatewayMessage() {
        setupMocks();

        Id accountId = idGen.newId(Account.SObjectType);
        Opportunity opp = createOpp('Closed Won', 100.0, accountId);
        Set<Id> oppIds = new Set<Id>{ opp.Id };

        when(mockSelector.selectById(oppIds)).thenReturn(new List<Opportunity>{ opp });
        when(mockGateway.authenticate()).thenThrow(new BillingException('Auth token expired'));

        try {
            InvoicingService.invoiceWonOpportunities(oppIds);
            System.assertFail('Expected InvoicingService.InvoicingException was not thrown');
        } catch (InvoicingService.InvoicingException e) {
            System.assert(
                e.getMessage().contains('Auth token expired'),
                'Exception message should contain the gateway message. Got: ' + e.getMessage()
            );
        }

        // authenticate was called
        verify(mockGateway, 1, 'authenticate').verify();
        // nothing invoiced
        verify(mockGateway, 0, 'createInvoice', anyId(), anyDecimal()).verify();
        // nothing registered or committed
        verify(mockUow, 0, 'registerDirty', anySObject()).verify();
        verify(mockUow, 0, 'commitWork').verify();
    }

    // ─── Contract 2: only Closed Won + Amount > 0 are invoiced ───

    @isTest
    private void test_onlyClosedWonWithPositiveAmountAreInvoiced() {
        setupMocks();

        Id acct1 = idGen.newId(Account.SObjectType);
        Id acct2 = idGen.newId(Account.SObjectType);
        Id acct3 = idGen.newId(Account.SObjectType);
        Id acct4 = idGen.newId(Account.SObjectType);

        Opportunity closedWonPositive = createOpp('Closed Won', 500.0,  acct1);
        Opportunity closedWonZero     = createOpp('Closed Won', 0.0,    acct2);
        Opportunity closedWonNull     = createOpp('Closed Won', null,   acct3);
        Opportunity openPositive      = createOpp('Open',       1000.0, acct4);

        Set<Id> oppIds = new Set<Id>{
            closedWonPositive.Id,
            closedWonZero.Id,
            closedWonNull.Id,
            openPositive.Id
        };

        when(mockSelector.selectById(oppIds)).thenReturn(
            new List<Opportunity>{ closedWonPositive, closedWonZero, closedWonNull, openPositive }
        );
        when(mockGateway.createInvoice(anyId(), anyDecimal())).thenReturn('INV-001');

        Integer result = InvoicingService.invoiceWonOpportunities(oppIds);

        System.assertEquals(1, result, 'Exactly one opportunity should be invoiced');
        // createInvoice called only for the qualifying opp
        verify(mockGateway, 1, 'createInvoice', anyId(), anyDecimal()).verify();
        verify(mockGateway, 1, 'createInvoice', acct1, 500.0).verify();
        // authenticate was called
        verify(mockGateway, 1, 'authenticate').verify();
    }

    // ─── Contract 3: successful invoice sets NextStep ───

    @isTest
    private void test_successfulInvoiceSetsNextStep() {
        setupMocks();

        Id accountId = idGen.newId(Account.SObjectType);
        Opportunity opp = createOpp('Closed Won', 250.0, accountId);
        Set<Id> oppIds = new Set<Id>{ opp.Id };

        when(mockSelector.selectById(oppIds)).thenReturn(new List<Opportunity>{ opp });
        when(mockGateway.createInvoice(accountId, 250.0)).thenReturn('INV-42');

        InvoicingService.invoiceWonOpportunities(oppIds);

        System.assertEquals(
            'Invoiced: INV-42',
            opp.NextStep,
            'NextStep should be "Invoiced: INV-42". Got: ' + opp.NextStep
        );
    }

    // ─── Contract 4: BillingException on one opp → failed fields set, others still invoiced ───

    @isTest
    private void test_billingFailureForOneOpportunity_othersStillInvoiced() {
        setupMocks();

        Id acct1 = idGen.newId(Account.SObjectType);
        Id acct2 = idGen.newId(Account.SObjectType);

        Opportunity opp1 = createOpp('Closed Won', 100.0, acct1);
        Opportunity opp2 = createOpp('Closed Won', 200.0, acct2);

        Set<Id> oppIds = new Set<Id>{ opp1.Id, opp2.Id };

        when(mockSelector.selectById(oppIds)).thenReturn(new List<Opportunity>{ opp1, opp2 });
        // General stub: returns invoice number
        when(mockGateway.createInvoice(anyId(), anyDecimal())).thenReturn('INV-001');
        // Specific stub for opp1: throws (registered after general, so it takes precedence for matching args)
        when(mockGateway.createInvoice(acct1, 100.0)).thenThrow(new BillingException('Payment declined'));

        Integer result = InvoicingService.invoiceWonOpportunities(oppIds);

        // Return value: only one succeeded
        System.assertEquals(1, result, 'Only one opportunity should be successfully invoiced');

        // Failed opp fields
        System.assertEquals(
            'Billing failed',
            opp1.NextStep,
            'Failed opp NextStep should be "Billing failed". Got: ' + opp1.NextStep
        );
        System.assertEquals(
            'Payment declined',
            opp1.Description,
            'Failed opp Description should be the exception message. Got: ' + opp1.Description
        );

        // Successful opp fields
        System.assertEquals(
            'Invoiced: INV-001',
            opp2.NextStep,
            'Successful opp NextStep should be "Invoiced: INV-001". Got: ' + opp2.NextStep
        );

        // Both opps registered, commitWork called once
        verify(mockUow, 2, 'registerDirty', anySObject()).verify();
        verify(mockUow, 1, 'commitWork').verify();
    }

    // ─── Contract 5: every processed opp is registered; commitWork called once ───

    @isTest
    private void test_registerDirtyCalledForEachProcessedAndCommitWorkOnce() {
