public class Application {
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork = new fflib_Application.UnitOfWorkFactory();
    public static final fflib_Application.ServiceFactory Service = new fflib_Application.ServiceFactory();
    public static final fflib_Application.SelectorFactory Selector = new fflib_Application.SelectorFactory();
    public static final fflib_Application.DomainFactory Domain = new Application.DomainFactory();

    static {
        // UnitOfWork – register SObject types
        UnitOfWork.registerSObject(Account.SObjectType);
        UnitOfWork.registerSObject(Contact.SObjectType);
        UnitOfWork.registerSObject(Opportunity.SObjectType);
        UnitOfWork.registerSObject(OpportunityContactRole.SObjectType);

        // UnitOfWork – register FK relationships so a single commit can
        // insert new Accounts, their Contacts & Opportunities, and
        // OpportunityContactRoles linking the new Opportunities and Contacts.
        UnitOfWork.registerFKLink(
            Contact.SObjectType, Contact.AccountId,
            Account.SObjectType, Account.Id
        );
        UnitOfWork.registerFKLink(
            Opportunity.SObjectType, Opportunity.AccountId,
            Account.SObjectType, Account.Id
        );
        UnitOfWork.registerFKLink(
            OpportunityContactRole.SObjectType, OpportunityContactRole.OpportunityId,
            Opportunity.SObjectType, Opportunity.Id
        );
        UnitOfWork.registerFKLink(
            OpportunityContactRole.SObjectType, OpportunityContactRole.ContactId,
            Contact.SObjectType, Contact.Id
        );

        // Service
        Service.registerService(IAccountsService.class, AccountsServiceImpl.class);

        // Selector
        Selector.registerSelector(Account.SObjectType, new AccountsSelector());
        Selector.registerSelector(Contact.SObjectType, new ContactsSelector());

        // Domain
        Domain.registerDomain(Account.SObjectType, new Accounts.Constructor());
    }

    /**
     * Custom domain factory that resolves records through the Application
     * Selector factory rather than issuing a raw SOQL query.
     */
    public class DomainFactory extends fflib_Application.DomainFactory {
        private fflib_ISObjectDomain mockDomain;

        public fflib_ISObjectDomain newInstance(Set<Id> sObjectIds) {
            if (mockDomain != null) {
                return mockDomain;
            }
            fflib_ISObjectSelector selector =
                (fflib_ISObjectSelector) Application.Selector.newInstance(Account.SObjectType);
            List<SObject> records = selector.selectSObjectsById(sObjectIds);
            return new Accounts((List<Account>) records);
        }

        public void setMock(fflib_ISObjectDomain mock) {
            this.mockDomain = mock;
        }

        public void resetMock() {
            this.mockDomain = null;
        }
    }
}
