public virtual class Opportunities extends fflib_SObjectDomain {

    public static final fflib_SObjectDomain.IConstructor Constructor = new Constructor();

    public virtual class Constructor implements fflib_SObjectDomain.IConstructable {
        public virtual Opportunities newInstance(Opportunity sobj) {
            return new Opportunities(sobj);
        }

        public virtual Opportunities newInstance(Map<Id, Opportunity> sobjs) {
            return new Opportunities(sobjs);
        }
    }

    public virtual Opportunities newInstance(Opportunity sobj) {
        super(sobj, Opportunity.SObjectType);
    }

    public virtual Opportunities newInstance(Map<Id, Opportunity> sobjs) {
        super(sobjs, Opportunity.SObjectType);
    }

    public virtual void afterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) getSObjects().values()) {
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }

    public virtual void afterUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Id id : getSObjects().keySet()) {
            Opportunity newOpp = (Opportunity) getSObjects().get(id);
            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(id);
            if (newOpp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                qualifyingIds.add(id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }
}
