public class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorMap = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorMap;
        }

        List<Contact> contactsToSave = new List<Contact>();

        for (Contact c : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds]) {
            if (c.Phone != null && c.Phone != '') {
                c.Phone = c.Phone.replaceAll('[^\\d+]', '');
                contactsToSave.add(c);
            }
        }

        if (!contactsToSave.isEmpty()) {
            List<Database.SaveResult> results = Database.update(contactsToSave, false);
            for (Database.SaveResult result : results) {
                if (!result.isSuccess()) {
                    errorMap.put(result.getId(), result.getErrors().get(0).getMessage());
                }
            }
        }

        return errorMap;
    }
}
