public class ErpCustomerSync implements Queueable {

    private final String accountId;
    private final String accountName;
    private final String country;

    public ErpCustomerSync(String accountId, String accountName, String country) {
        this.accountId   = accountId;
        this.accountName = accountName;
        this.country     = country;
    }

    public void execute(QueueableContext context) {
        // "country" must be JSON null when the field is blank
        String countryValue = String.isNotBlank(country) ? country : null;

        List<Map<String, Object>> payload = new List<Map<String, Object>> {
            new Map<String, Object> {
                'salesforceId' => accountId,
                'name'         => accountName,
                'country'      => countryValue
            }
        };

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));

        HttpResponse res = new Http().send(req);
        // Expected: 202 Accepted.
        // Error handling and retries are out of scope for this ticket.
    }
}
