    // When we stay within the limit, enqueue one job per case for full isolation.
    // When we exceed it, hand the full list to a single dispatcher job that
    // chains itself, still producing one independent job per case.
    if (eligibleCaseIds.size() <= 50) {
        for (Id cId : eligibleCaseIds) {
            System.enqueueJob(new CaseSurveyJob(cId));
        }
    } else {
        System.enqueueJob(new CaseSurveyJob(eligibleCaseIds));
    }
}
