    unsubscribe() {
        if (this._subscription) {
            const subscription = this._subscription;
            this._subscription = undefined;
            this.messageContext.unsubscribe(subscription);
        }
    }

    handleMessage(message) {
        this.selectedRecordId = message.recordId || null;
