import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    errorMessage;
    hasData = false;

    _inFlight = false;
    _pollingInterval = null;
    _visibilityHandler = null;

    connectedCallback() {
        this._visibilityHandler = () => this._handleVisibilityChange();
        document.addEventListener('visibilitychange', this._visibilityHandler);
        this._startPolling();
        this._fetchStats();
    }

    disconnectedCallback() {
        this._stopPolling();
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
    }

    _startPolling() {
        this._stopPolling();
        this._pollingInterval = setInterval(() => {
            this._fetchStats();
        }, 60000);
    }

    _stopPolling() {
        if (this._pollingInterval !== null) {
            clearInterval(this._pollingInterval);
            this._pollingInterval = null;
        }
    }

    _handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this._fetchStats();
        }
    }

    async _fetchStats() {
        if (this._inFlight) return;
        if (document.visibilityState === 'hidden') return;

        this._inFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.errorMessage = null;
            this.hasData = true;
        } catch (error) {
            this.errorMessage = error.body.message;
        } finally {
            this._inFlight = false;
        }
    }
}
