import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        this._initActiveIndex();
    }

    _value = '';
    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val ?? '';
        this._syncActiveIndex();
    }

    _activeIndex = 0;

    get displayOptions() {
        return this._options.map((opt, i) => ({
            value: opt.value,
            label: opt.label,
            id: `status-listbox-opt-${i}`,
            selected: String(opt.value === this._value)
        }));
    }

    get activeDescendantId() {
        if (!this._options.length) return '';
        const idx = Math.max(0, Math.min(this._activeIndex, this._options.length - 1));
        return `status-listbox-opt-${idx}`;
    }

    connectedCallback() {
        this._initActiveIndex();
    }

    _initActiveIndex() {
        if (!this._options.length) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx >= 0 ? idx : 0;
    }

    _syncActiveIndex() {
        if (!this._options.length) return;
        const idx = this._options.findIndex((o) => o.value === this._value);
        if (idx >= 0) {
            this._activeIndex = idx;
        }
    }

    handleKeydown(event) {
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!handledKeys.includes(event.key)) return;

        event.preventDefault();

        if (!this._options.length) return;

        // Clamp to valid range as a safety guard
        this._activeIndex = Math.max(0, Math.min(this._activeIndex, this._options.length - 1));

        switch (event.key) {
            case 'ArrowDown':
                if (this._activeIndex < this._options.length - 1) {
                    this._activeIndex++;
                }
                break;
            case 'ArrowUp':
                if (this._activeIndex > 0) {
                    this._activeIndex--;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this._selectIndex(this._activeIndex);
                break;
        }
    }

    handleOptionClick(event) {
        const li = event.currentTarget;
        const val = li.dataset.value;
        const idx = this._options.findIndex((o) => o.value === val);
        if (idx < 0) return;
        this._activeIndex = idx;
        this._selectIndex(idx);
    }

    _selectIndex(index) {
        const opt = this._options[index];
        if (!opt || opt.value === this._value) return;
        this._value = opt.value;
        this.dispatchEvent(
            new CustomEvent('change', { detail: { value: opt.value } })
        );
    }
}
