public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Stage one NPSP Data Import record per gift
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c      = gift.firstName,
                npsp__Contact1_Lastname__c       = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c         = gift.amount,
                npsp__Donation_Date__c           = gift.giftDate,
                npsp__Donation_Donor__c          = 'Contact1'
            );
            dataImports.add(di);
        }

        // Persist the staging records (audit trail remains in the org)
        insert dataImports;

        // Collect IDs in input order
        List<Id> importIds = new List<Id>();
        for (npsp__DataImport__c di : dataImports) {
            importIds.add(di.Id);
        }

        // Process synchronously via NPSP's Data Import Apex API
        // Uses the org's Data Import Settings (npsp__Data_Import_Settings__c) for
        // contact matching (first name, last name, email) and donation rules.
        NPE5_DataImport.processDataImport(importIds);

        // Query back the processed records to read NPSP's results
        Map<Id, npsp__DataImport__c> resultMap = new Map<Id, npsp__DataImport__c>(
            [SELECT Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :importIds]
        );

        // Build one ImportResult per gift, preserving input order
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c di : dataImports) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c processed = resultMap.get(di.Id);

            if (processed != null && 'Imported' == processed.npsp__Status__c) {
                result.success     = true;
                result.contactId   = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
            } else {
                result.success = false;
                result.errorMessage = (processed != null)
                    ? processed.npsp__FailureInformation__c
                    : 'Unknown processing error';
            }

            results.add(result);
        }

        return results;
    }
}
```

**Key design decisions:**

| Concern | How it's handled |
|---|---|
| **Audit trail** | `npsp__DataImport__c` records are inserted and never deleted; they remain in the org. |
| **Synchronous, same transaction** | `NPE5_DataImport.processDataImport(importIds)` is a synchronous NPSP API call that runs in the current transaction (no Queueable / Batch / `@future`). |
| **Org Data Import settings** | NPSP's processor reads `npsp__Data_Import_Settings__c` internally to determine matching rules (first name + last name + email) and donation-matching behaviour. We don't need to pass or configure anything. |
| **Order preservation** | The `dataImports` list is built in input order; after insert each record's `Id` is set in that same order, so iterating `dataImports` to build results preserves the original gift order. |
| **Failure isolation** | Each Data Import row is processed independently by NPSP. A failed row gets `npsp__Status__c = 'Failed'` and a `npsp__FailureInformation__c` message; the others continue unaffected. |
| **Bulk safety (200 gifts)** | One `insert` of up to 200 records, one SOQL of up to 200 rows, one API call with a list of IDs—well within governor limits. |
| **Null / empty input** | Early return of an empty list. |

