public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all existing GAU allocations on the given opportunity with new
     * allocations based on the supplied percentage map.
     *
     * The stored percentage drives automatic recalculation of amounts when the
     * opportunity amount changes (handled by NPSP platform logic).
     *
     * @param opportunityId   Id of the Opportunity (npsp__Opportunity__c lookup)
     * @param percentByGauId  Keys are npsp__General_Accounting_Unit__c Ids;
     *                        values are percentages where 60 means 60%.
     * @return List of inserted npsp__Allocation__c records
     * @throws AllocationException on any validation failure
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ── Validation ──────────────────────────────────────────────────────
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percentage map must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Map.Entry<Id, Decimal> entry : percentByGauId.entrySet()) {
            Decimal pct = entry.getValue();
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Each percentage must be a value greater than 0. '
                    + 'Invalid value for GAU ' + entry.getKey() + ' : ' + pct
                );
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Total percentages (' + totalPercent + ') exceed 100%.'
            );
        }

        // Verify GAUs exist and are active
        Set<Id> gauIdSet = new Set<Id>(percentByGauId.keySet());
        Map<Id, npsp__General_Accounting_Unit__c> gauMap =
            new Map<Id, npsp__General_Accounting_Unit__c>(
                [
                    SELECT Id, Name, npsp__Active__c
                    FROM npsp__General_Accounting_Unit__c
                    WHERE Id IN :gauIdSet
                ]
            );

        for (Id gauId : gauIdSet) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU not found: ' + gauId);
            }
            if (!gau.npsp__Active__c) {
                throw new AllocationException(
                    'GAU is inactive: ' + gau.Name + ' (' + gauId + ')'
                );
            }
        }

        // ── Fetch opportunity amount ────────────────────────────────────────
        Opportunity opp = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];

        // ── Delete existing allocations ─────────────────────────────────────
        List<npsp__Allocation__c> existingAllocs = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocs.isEmpty()) {
            delete existingAllocs;
        }

        // ── Build and insert new allocations ────────────────────────────────
        // Storing npsp__Percent__c ensures NPSP's standard recalculation logic
        // will keep npsp__Amount__c in sync when the opportunity amount changes.
        List<npsp__Allocation__c> newAllocs = new List<npsp__Allocation__c>();
        for (Map.Entry<Id, Decimal> entry : percentByGauId.entrySet()) {
            Decimal pct = entry.getValue();
            Decimal amount = (opp.Amount != null ? opp.Amount : 0) * pct / 100;

            newAllocs.add(new npsp__Allocation__c(
                npsp__Opportunity__c             = opportunityId,
                npsp__General_Accounting_Unit__c = entry.getKey(),
                npsp__Percent__c                 = pct,
                npsp__Amount__c                  = amount
            ));
        }

        insert newAllocs;
        return newAllocs;
    }
}
```

**How the auto-adjust requirement is met:**

Each allocation stores its `npsp__Percent__c` (e.g., 60). NPSP's platform-level logic (trigger/flow on `npsp__Allocation__c` or a formula that references the parent opportunity) recalculates `npsp__Amount__c = Opportunity.Amount × npsp__Percent__c / 100` whenever the opportunity amount changes. So a $1,000 gift split 60/40 becomes $1,200 / $800 automatically when the opportunity is corrected to $2,000 — no additional Apex from this class is needed.

