        // Set npsp__Contact_Role_ID__c on all PSCs
        for (npsp__Partial_Soft_Credit__c psc : newPscs) {
            psc.npsp__Contact_Role_ID__c = String.valueOf(ocrIdMap.get(pscKeyMap.get(psc)));
