public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // Validate amount
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-zero value.');
        }

        // Fetch the contact
        Contact contact = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
        ];

        if (contact == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        // Build the opportunity name: "FirstName LastName Donation yyyy-MM-dd"
        String oppName = contact.FirstName + ' ' + contact.LastName + ' Donation ' + giftDate.format('yyyy-MM-dd');

        // Create the Closed Won opportunity on the household account
        Opportunity opp = new Opportunity(
            Name                 = oppName,
            AccountId            = contact.AccountId,
            StageName            = 'Closed Won',
            Amount               = amount,
            CloseDate            = giftDate,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        // Query all other contacts in the same household
        List<Contact> otherMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :contact.AccountId
              AND Id != :contactId
        ];

        // Build contact roles
        List<ContactRole> roles = new List<ContactRole>();

        // Primary contact gets the Donor role
        roles.add(new ContactRole(
            ContactId     = contactId,
            OpportunityId = opp.Id,
            ContactRole   = 'Donor'
        ));

        // Every other household member gets the Household Member role
        for (Contact member : otherMembers) {
            roles.add(new ContactRole(
                ContactId     = member.Id,
                OpportunityId = opp.Id,
                ContactRole   = 'Household Member'
            ));
        }

        insert roles;

        // Create the single paid payment for the full amount
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c   = opp.Id,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c   = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c           = true
        );
        insert payment;

        return opp.Id;
    }
}
