public class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
            'Another contact on this account already uses this email address.';

    /**
     * Before insert: check that no new contact shares an email (case-insensitive)
     * with an existing contact on the same account, and that no two contacts in the
     * same batch share the same account + email.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = (List<Contact>) triggerNew;

        // Identify records that have both AccountId and a non-blank Email
        Map<Integer, String> recordKeys = new Map<Integer, String>();
        List<List<Object>> searchPairs = new List<List<Object>>();

        for (Integer i = 0; i < contacts.size(); i++) {
            Contact c = contacts[i];
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                String key = c.AccountId + '|' + c.Email.toLowerCase();
                recordKeys.put(i, key);
                searchPairs.add(new List<Object>{ c.AccountId, c.Email });
            }
        }

        if (recordKeys.isEmpty()) {
            return;
        }

        // Single SOQL query: find existing contacts with the same (AccountId, Email)
        Map<String, Set<Id>> existingByKey = new Map<String, Set<Id>>();
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE (AccountId, Email) IN :searchPairs
        ];
        for (Contact ec : existingContacts) {
            String key = ec.AccountId + '|' + ec.Email.toLowerCase();
            if (!existingByKey.containsKey(key)) {
                existingByKey.put(key, new Set<Id>());
            }
            existingByKey.get(key).add(ec.Id);
        }

        // Process in order: first record claiming a key is accepted, later ones rejected
        Set<String> claimedKeys = new Set<String>();
        for (Integer i = 0; i < contacts.size(); i++) {
            if (!recordKeys.containsKey(i)) {
                continue;
            }
            String key = recordKeys.get(i);

            Boolean hasDbConflict =
                    existingByKey.containsKey(key) && !existingByKey.get(key).isEmpty();
            Boolean hasBatchConflict = claimedKeys.contains(key);

            if (hasDbConflict || hasBatchConflict) {
                contacts[i].addError(ERROR_MESSAGE);
            } else {
                claimedKeys.add(key);
            }
        }
    }

    /**
     * Before update: only check contacts whose Email or AccountId changed.
     * A contact never conflicts with itself.
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        // Identify records where Email or AccountId changed and new values are non-blank
        Map<Integer, String> recordKeys = new Map<Integer, String>();
        Map<Integer, Id> recordIds = new Map<Integer, Id>();
        List<List<Object>> searchPairs = new List<List<Object>>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact newC = newContacts[i];
            Contact oldC = oldContacts[i];

            Boolean emailChanged = newC.Email != oldC.Email;
            Boolean accountIdChanged = newC.AccountId != oldC.AccountId;

            if (!emailChanged && !accountIdChanged) {
                continue;
            }
            if (newC.AccountId == null || String.isBlank(newC.Email)) {
                continue;
            }

            String key = newC.AccountId + '|' + newC.Email.toLowerCase();
            recordKeys.put(i, key);
            recordIds.put(i, newC.Id);
            searchPairs.add(new List<Object>{ newC.AccountId, newC.Email });
        }

        if (recordKeys.isEmpty()) {
            return;
        }

        // Single SOQL query
        Map<String, Set<Id>> existingByKey = new Map<String, Set<Id>>();
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE (AccountId, Email) IN :searchPairs
        ];
        for (Contact ec : existingContacts) {
            String key = ec.AccountId + '|' + ec.Email.toLowerCase();
            if (!existingByKey.containsKey(key)) {
                existingByKey.put(key, new Set<Id>());
            }
            existingByKey.get(key).add(ec.Id);
        }

        // Process in order: exclude self, first record claiming a key is accepted
        Set<String> claimedKeys = new Set<String>();
        for (Integer i = 0; i < newContacts.size(); i++) {
            if (!recordKeys.containsKey(i)) {
                continue;
            }
            String key = recordKeys.get(i);
            Id selfId = recordIds.get(i);

            // DB conflict: any existing contact with this key that is not self
            Boolean hasDbConflict = false;
            if (existingByKey.containsKey(key)) {
                for (Id existingId : existingByKey.get(key)) {
                    if (existingId != selfId) {
                        hasDbConflict = true;
                        break;
                    }
                }
            }

            Boolean hasBatchConflict = claimedKeys.contains(key);

            if (hasDbConflict || hasBatchConflict) {
                newContacts[i].addError(ERROR_MESSAGE);
            } else {
                claimedKeys.add(key);
            }
        }
    }
}
