public class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject sobj : triggerNew) {
            Contact c = (Contact) sobj;
            if (c.AccountId == null) {
                continue;
            }

            Account acc = accountsById.get(c.AccountId);
            if (acc == null) {
                continue;
            }

            if (String.isBlank(c.MailingStreet)
                && String.isBlank(c.MailingCity)
                && String.isBlank(c.MailingPostalCode)
                && String.isBlank(c.MailingCountry)) {
                c.MailingStreet = acc.BillingStreet;
                c.MailingCity = acc.BillingCity;
                c.MailingPostalCode = acc.BillingPostalCode;
                c.MailingCountry = acc.BillingCountry;
            }
        }
    }
}
